import json

def sse(data, event=None, id=None):
    lines = []
    if event:
        lines.append(f"event: {event}")
    if id is not None:
        lines.append(f"id: {id}")
    for part in str(data).split("\n"):
        lines.append(f"data: {part}")
    return "\n".join(lines) + "\n\n"

msg = sse(json.dumps({"pct": 50}), event="progress", id=3) + sse("line1\nline2")
print(msg.count("\n\n"))
